import React,{useState} from 'react';
export default function Storyboard({state='ready'}){const [selected,setSelected]=useState(0);const [note,setNote]=useState('Open on a quiet street.');if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
const frames=['Establish','Discover','Resolve'];return <div className="shell"><span className="eyebrow">Creative workspace</span><h1>Give the story a shape before the render.</h1><p>Explore a local three-beat sequence and edit its direction.</p><div className="grid">{frames.map((label,i)=><button id={'frame-'+i} key={label} className="panel" onClick={()=>setSelected(i)} aria-pressed={selected===i}><svg viewBox="0 0 250 140" role="img" aria-label={label+' reference composition'}><rect width="250" height="140" rx="12" fill="var(--soft)"/><circle cx={60+i*45} cy="55" r="24" fill="var(--primary)"/><path d="M0 125 L85 80 L150 125 L210 70 L250 125" fill="var(--border)"/></svg><h2>{label}</h2></button>)}</div><section className="panel spacer"><h2 id="result">{frames[selected]}: direction</h2><label>Scene notes<textarea aria-label="Scene notes" rows={3} value={note} onChange={e=>setNote(e.currentTarget.value)}/></label><p className="muted">Draft notes stay local to this preview.</p></section></div>;}
